import base64
IPA_DATA=''
"""Add Wakhan's fixed iPhone download without replacing the backend or database."""
import fcntl,hashlib,hmac,io,json,os,plistlib,sqlite3,struct,subprocess,sys,time,urllib.request,zipfile
from pathlib import Path

LIVE=Path('/opt/wakhan-app-0.2.11-li9z037x')
STATE=Path('/opt/wakhan-ios-download-0.2.12')
UNIT=Path('/etc/systemd/system/wakhan-app.service')
REPORT=Path('/root/wakhan-ios-0212-result.zip')
BASE_SHA='8b29c0ba460603784a34af67accab757c10b9d0430811945d7ec977d5f6413c3'
IPA_SHA='7512fff8780d1e2f01adb504dc72782f9978f02ab875b6ec80410d3667fc1798'
APK_SHA='ab6b6566afe774dde309f8f67102def1d49c1f83b12bcdc7e1c4fbbd9e4329a2'
PUBLIC='https://music.kabulcafe.uk/download/Wakhan.ipa?build=26'
ANCHOR="    async def cinema_lock(request):\n"
HANDLER='''    async def download_ios(request):
        path=root/'releases/Wakhan.ipa'
        if not path.is_file() or path.is_symlink():raise web.HTTPNotFound()
        return web.FileResponse(path,headers={'Content-Type':'application/octet-stream',
            'Content-Disposition':'attachment; filename="Wakhan.ipa"','Cache-Control':'no-store'})
'''
ROUTE="    app.router.add_get('/download/Wakhan.ipa',download_ios)\n"

def require(value,code):
    if not value:raise RuntimeError(code)

def digest(data):return hashlib.sha256(data).hexdigest()
def sha(path):return digest(Path(path).read_bytes())

def patch_runtime(raw):
    source=raw.decode();require(source.count(ANCHOR)==1,'RUNTIME_DOWNLOAD_ANCHOR_CHANGED')
    require(source.count("    app.router.add_get('/s/{f}',")==1,'RUNTIME_ROUTES_CHANGED')
    require('async def download_ios(' not in source,'UNEXPECTED_IOS_HANDLER')
    source=source.replace(ANCHOR,HANDLER+ANCHOR,1)
    at=source.index("    app.router.add_get('/s/{f}',")
    source=source[:at]+ROUTE+source[at:]
    compile(source,'native_runtime.py','exec');return source.encode()

def command(args):
    result=subprocess.run(args,capture_output=True,text=True,timeout=45)
    require(result.returncode==0,'SERVICE_COMMAND_FAILED');return result.stdout

def restart():command(['systemctl','restart','wakhan-app.service'])

def local_get(path,key=None,method='GET',headers=None):
    request=urllib.request.Request('http://127.0.0.1:10010'+path,
        headers={**({'X-Init':key} if key else {}),**(headers or {})},method=method)
    with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(request,timeout=6) as response:
        return response.status,dict(response.headers),response.read()

def local_json(path,key=None):return json.loads(local_get(path,key)[2])

def session_key(settings):
    secret=Path(settings['session_key_file']).read_bytes();require(len(secret)==32,'SESSION_KEY_CHANGED')
    with sqlite3.connect(Path(settings['database']).as_uri()+'?mode=ro',uri=True,timeout=5) as db:
        row=db.execute('select sid from wka_sessions where uid=? order by seen desc limit 1',(8878966292,)).fetchone()
    require(bool(row),'EXISTING_OWNER_SESSION_REQUIRED');sid=row[0]
    return 'wka1.'+sid+'.'+hmac.new(secret,sid.encode(),hashlib.sha256).hexdigest()[:32]

def ready(key):
    deadline=time.monotonic()+25
    while True:
        try:
            require(local_json('/health').get('version')=='0.2.11-beta','BACKEND_HEALTH_CHANGED')
            require(local_json('/api/me',key).get('me',{}).get('public_id')==77777777,'EXISTING_SESSION_FAILED')
            return
        except Exception:
            if time.monotonic()>=deadline:raise RuntimeError('BACKEND_RESTART_CHECK_FAILED')
            time.sleep(.4)

def atomic(path,data,owner=None,mode=0o600):
    path=Path(path);temporary=path.with_name('.'+path.name+'.ios0212-tmp')
    fd=os.open(temporary,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    try:
        with os.fdopen(fd,'wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
        if owner is not None:os.chown(temporary,owner.st_uid,owner.st_gid)
        temporary.chmod(mode);temporary.replace(path)
    finally:
        if temporary.exists():temporary.unlink()

def validate_ipa(data):
    require(len(data)==2057528 and digest(data)==IPA_SHA,'IPHONE_DOWNLOAD_INVALID')
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        root='Payload/App.app/'
        info=plistlib.loads(archive.read(root+'Info.plist'))
        require(info.get('CFBundleIdentifier')=='app.wakhan.music' and info.get('CFBundleVersion')=='26'
            and info.get('CFBundleShortVersionString')=='0.2.12','IPHONE_VERSION_INVALID')
        binary=archive.read(root+info['CFBundleExecutable'])
        require(binary[:4]==b'\xcf\xfa\xed\xfe' and struct.unpack_from('<I',binary,4)[0]==0x100000c,'IPHONE_ARM64_REQUIRED')
        require(b'WakhanAudioSessionPlugin' in binary and b'wakhanKeyboardFrame' in binary,'IPHONE_NATIVE_COMPONENTS_MISSING')
        raw=archive.read(root+'public/wakhan-shell.json');meta=json.loads(archive.read(root+'public/wakhan-release.json'))
        require(meta['build']==26 and meta['shell_sha256']==digest(raw),'IPHONE_ASSETS_INVALID')
        require(json.loads(archive.read(root+'public/build-flags.json')).get('push') is False,'IPHONE_SIDELOAD_FLAGS_INVALID')

def verify_serving(key):
    ready(key)
    status,headers,body=local_get('/download/Wakhan.ipa');require(status==200 and digest(body)==IPA_SHA,'IPHONE_ROUTE_CHECK_FAILED')
    headers={key.lower():value for key,value in headers.items()}
    require(headers.get('content-type','').startswith('application/octet-stream') and 'attachment' in headers.get('content-disposition',''),'IPHONE_ATTACHMENT_HEADERS_INVALID')
    status,_,body=local_get('/download/Wakhan.ipa',headers={'Range':'bytes=0-15'})
    require(status==206 and body==b'PK\x03\x04'+(LIVE/'releases/Wakhan.ipa').read_bytes()[4:16],'IPHONE_RANGE_CHECK_FAILED')
    require(digest(local_get('/download/Wakhan.apk')[2])==APK_SHA,'ANDROID_DOWNLOAD_CHANGED')

def publish(data,report):
    validate_ipa(data)
    runtime=LIVE/'native_runtime.py';target=LIVE/'releases/Wakhan.ipa';apk=LIVE/'releases/Wakhan.apk'
    require(not LIVE.is_symlink() and not runtime.is_symlink() and not target.is_symlink()
        and not (LIVE/'releases').is_symlink(),'EXPECTED_OWNED_PATHS_REQUIRED')
    require(sha(apk)==APK_SHA,'CURRENT_ANDROID_BUILD_REQUIRED')
    old=runtime.read_bytes();backup=STATE/'native_runtime.before.py'
    if digest(old)!=BASE_SHA:
        require(backup.is_file() and sha(backup)==BASE_SHA and patch_runtime(backup.read_bytes())==old,'NATIVE_SOURCE_CHANGED')
        require(target.is_file() and sha(target)==IPA_SHA,'INSTALLED_IPHONE_FILE_CHANGED')
        settings=json.loads((LIVE/'private/app.json').read_text());verify_serving(session_key(settings))
        report.update(ok=True,already_installed=True,url=PUBLIC,runtime_sha256=digest(old));return
    require(command(['systemctl','is-active','wakhan-app.service']).strip()=='active','NATIVE_SERVICE_REQUIRED')
    execution=command(['systemctl','show','wakhan-app.service','-p','ExecStart','--value'])
    require(str(runtime) in execution,'NATIVE_SERVICE_PATH_CHANGED')
    settings=json.loads((LIVE/'private/app.json').read_text())
    require(settings.get('base')==str(LIVE) and settings.get('database')=='/opt/wakhan-music/data/music.db','NATIVE_SETTINGS_CHANGED')
    key=session_key(settings);ready(key)
    require(not target.exists() or sha(target)==IPA_SHA,'UNEXPECTED_IPHONE_DOWNLOAD_EXISTS')
    modified=patch_runtime(old);runtime_owner=runtime.stat();file_owner=apk.stat();unit_sha=sha(UNIT)
    atomic(backup,old);existed=target.exists();changed=False
    try:
        atomic(target,data,file_owner,file_owner.st_mode&0o777)
        atomic(runtime,modified,runtime_owner,runtime_owner.st_mode&0o777);changed=True
        restart();verify_serving(key)
        require(sha(UNIT)==unit_sha,'SERVICE_UNIT_CHANGED')
        state={'version':'0.2.12-beta','build':26,'ipa_sha256':IPA_SHA,'runtime_sha256':digest(modified),'original_runtime_sha256':BASE_SHA,'url':PUBLIC}
        atomic(STATE/'installed.json',(json.dumps(state,indent=2)+'\n').encode())
        report.update(ok=True,url=PUBLIC,runtime_sha256=digest(modified),existing_session_verified=True,range_verified=True)
    except BaseException:
        if changed:atomic(runtime,old,runtime_owner,runtime_owner.st_mode&0o777);restart();ready(key)
        if not existed and target.is_file() and sha(target)==IPA_SHA:target.unlink()
        report['previous_backend_restored']=sha(runtime)==BASE_SHA
        raise

def main():
    require(os.geteuid()==0,'RUN_AS_ROOT');os.umask(0o077)
    require(not STATE.is_symlink(),'STATE_PATH_CHANGED');STATE.mkdir(mode=0o700,exist_ok=True)
    report={'ok':False,'version':'0.2.12-beta','build':26,'database_changes':False,'device_verified':False,'store_ready':False}
    with (STATE/'publish.lock').open('w') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        try:
            publish(base64.b64decode(IPA_DATA),report)
        except Exception as error:
            message=str(error);report['error']=message if isinstance(error,RuntimeError) and message.isupper() and len(message)<100 else type(error).__name__
        with zipfile.ZipFile(REPORT,'w',zipfile.ZIP_DEFLATED) as archive:archive.writestr('result.json',json.dumps(report,indent=2))
        REPORT.chmod(0o600)
        print('IPHONE_DOWNLOAD_READY: '+PUBLIC if report['ok'] else 'PUBLISH_NEEDS_REVIEW: '+report.get('error','unknown'))
        print('REPORT_READY: '+str(REPORT))

if __name__=='__main__':main()
